const payload = $json.body || $json || {};
const message = String(payload.message || '').trim();
const lang = payload.lang === 'en' ? 'en' : 'ar';
const countryCode = String(payload.countryCode || 'AE').toUpperCase();
const pageUrl = String(payload.pageUrl || '/');
const history = Array.isArray(payload.history) ? payload.history.slice(-6) : [];
const ctx = payload.siteContext || {};

const historyText = history.length
  ? history.map((h) => `${h.role === 'user' ? 'Customer' : 'Asra3 Support'}: ${h.content}`).join('\n')
  : 'None (first turn)';

const userPrompt = [
  `Customer Language Preference: ${lang === 'ar' ? 'Arabic (respond in clear friendly Arabic unless user writes English)' : 'English (respond in clear friendly English unless user writes Arabic)'}`,
  `Active Country Hub: ${countryCode} | Current Page: ${pageUrl}`,
  `LIVE ASRA3.COM CONTEXT (ALWAYS USE THESE EXACT LIVE PRICES & OFFERS):`,
  JSON.stringify(ctx, null, 2),
  ``,
  `RECENT CONVERSATION HISTORY:`,
  historyText,
  ``,
  `LATEST CUSTOMER MESSAGE:`,
  message,
].join('\n');

return [{
  json: {
    userPrompt,
    lang,
    countryCode,
    pageUrl,
    originalMessage: message,
  },
}];

const rawOutput = String($json.output || $json.text || '').trim();
const prep = $('prepareContext').first().json || {};
const isAr = prep.lang === 'ar' || /[\u0600-\u06FF]/.test(prep.originalMessage || '');

const cleaned = rawOutput
  .replace(/^```(?:json)?\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

let parsed = null;
try {
  parsed = JSON.parse(cleaned);
} catch {
  const match = cleaned.match(/\{[\s\S]*\}/);
  if (match) {
    try {
      parsed = JSON.parse(match[0]);
    } catch {
      parsed = null;
    }
  }
}

const reply = (parsed && typeof parsed.reply === 'string' && parsed.reply.trim())
  ? parsed.reply.trim()
  : (cleaned || (isAr
      ? 'أهلاً بك في دعم أسرع! كيف يمكنني مساعدتك بخصوص الباقات أو الوظائف؟'
      : 'Welcome to Asra3 Support! How can I assist you with packages or GCC jobs?'));

const showLeadForm = Boolean(parsed && parsed.showLeadForm);
const suggestedActions = Array.isArray(parsed?.suggestedActions)
  ? parsed.suggestedActions.map((s) => String(s || '').trim()).filter(Boolean).slice(0, 4)
  : (isAr
      ? ['الأسعار والعروض الحالية', 'أريد التواصل مع الدعم']
      : ['Pricing & Offers', 'Contact Human Support']);
const capturedLead = (parsed && parsed.capturedLead && typeof parsed.capturedLead === 'object')
  ? parsed.capturedLead
  : null;

return [{
  json: {
    reply,
    showLeadForm,
    suggestedActions,
    capturedLead,
  },
}];
